"""Managed database connection pool."""

from typing import List, Optional


class ConnectionHandle:
    def __init__(self, conn_id: int):
        self.conn_id = conn_id
        self.in_use: bool = False


class ConnectionPool:
    def __init__(self, size: int = 3):
        self.size = size
        self.handles = [ConnectionHandle(i) for i in range(size)]

    def acquire(self) -> Optional[ConnectionHandle]:
        for h in self.handles:
            if not h.in_use:
                h.in_use = True
                return h
        return None

    def release(self, handle: ConnectionHandle) -> None:
        handle.in_use = False

    @property
    def available_count(self) -> int:
        return sum(1 for h in self.handles if not h.in_use)

